css:
.d-vc{position:relative;width:100%;max-width:340px;border:1px solid var(--line);border-radius:10px;background:var(--paper);overflow:hidden;outline:none}
.d-vc:focus-visible{outline:1px solid var(--ink);outline-offset:2px}
.d-vc-frame{position:relative;display:flex;align-items:flex-end;justify-content:space-between;height:120px;padding:10px 12px;background:linear-gradient(150deg,color-mix(in srgb,var(--ink) 82%,var(--paper)),color-mix(in srgb,var(--ink) 55%,var(--paper)));color:var(--paper)}
.d-vc-frame span,.d-vc-frame em{font-family:var(--font-mono);font-size:9px;letter-spacing:.06em;font-style:normal;opacity:.85}
.d-vc-bar{position:relative;height:6px;background:var(--line);cursor:pointer}
.d-vc-buf{position:absolute;left:0;top:0;bottom:0;width:62%;background:color-mix(in srgb,var(--ink) 18%,transparent)}
.d-vc-play{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--ink)}
.d-vc-row{display:flex;align-items:center;justify-content:space-between;padding:8px 12px}
.d-vc-toggle{width:30px;height:30px;border:1px solid var(--line);border-radius:999px;background:var(--bg);color:var(--ink);font:inherit;font-size:11px;cursor:pointer}
.d-vc-row span{font-family:var(--font-mono);font-size:10px;color:var(--faint)}

init:
root => {
  var box = root.querySelector('[data-player]');
  var fill = root.querySelector('[data-fill]');
  var tc = root.querySelector('[data-tc]');
  var st = root.querySelector('[data-state]');
  var btn = root.querySelector('[data-toggle]');
  var bar = root.querySelector('[data-bar]');
  if (!box || !fill || !bar) return;
  var dur = 42, t = 0, playing = false, timer = 0;
  var fmt = function (s) { return '00:' + (s < 10 ? '0' : '') + Math.floor(s); };
  var paint = function () { fill.style.width = (t / dur * 100).toFixed(2) + '%'; if (tc) tc.textContent = fmt(t); };
  var tick = function () { t = Math.min(dur, t + .25); paint(); if (t >= dur) pause(); };
  var play = function () { if (playing) return; playing = true; if (btn) btn.textContent = '❚❚'; if (st) st.textContent = '播放中'; timer = setInterval(tick, 250); };
  var pause = function () { playing = false; clearInterval(timer); if (btn) btn.textContent = '▶'; if (st) st.textContent = '暂停'; };
  if (btn) btn.addEventListener('click', function () { playing ? pause() : play(); });
  box.addEventListener('keydown', function (e) { if (e.key === ' ') { e.preventDefault(); playing ? pause() : play(); } });
  bar.addEventListener('pointerdown', function (e) { var r = bar.getBoundingClientRect(); t = Math.max(0, Math.min(dur, (e.clientX - r.left) / r.width * dur)); paint(); });
  paint();
}
